<?php
require __DIR__.'/config.php';$u=require_role('customer');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='profile'){verify_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');if(mb_strlen($name)<2||mb_strlen($phone)<6)flash('Please enter valid details.','danger');else{$s=$pdo->prepare('UPDATE users SET name=?,phone=? WHERE id=?');$s->execute([$name,$phone,$u['id']]);$_SESSION['user']['name']=$name;$_SESSION['user']['phone']=$phone;flash('Profile updated.');}redirect('dashboard.php?section=profile');}
$s=$pdo->prepare('SELECT b.*,c.name AS car_name,c.image_url FROM bookings b JOIN cars c ON c.id=b.car_id WHERE b.user_id=? ORDER BY b.created_at DESC');$s->execute([$u['id']]);$bookings=$s->fetchAll();$section=$_GET['section']??'overview';$active=count(array_filter($bookings,fn($b)=>in_array($b['status'],['Pending','Confirmed'],true)));$pageTitle='Customer Dashboard';require __DIR__.'/partials/header.php';
?>
<div class="dashboard-shell"><div class="row g-0"><aside class="col-lg-2 dash-sidebar"><div class="dash-brand">🚘 MODERN<br>CAR RENT</div><div class="small text-white-50 px-2 mb-2">CUSTOMER MENU</div><nav class="nav flex-column"><a class="nav-link <?=$section==='overview'?'active':''?>" href="dashboard.php">▦ &nbsp; Dashboard</a><a class="nav-link <?=$section==='bookings'?'active':''?>" href="dashboard.php?section=bookings">▣ &nbsp; My Bookings</a><a class="nav-link" href="index.php#fleet">🚗 &nbsp; Explore Cars</a><a class="nav-link <?=$section==='profile'?'active':''?>" href="dashboard.php?section=profile">⚙ &nbsp; My Profile</a><a class="nav-link" href="logout.php">↪ &nbsp; Logout</a></nav><div class="mt-5 px-2 small text-white-50">Your journey,<br>made easier.</div></aside><div class="col-lg-10"><div class="dash-topbar d-flex justify-content-between"><strong>Customer Dashboard</strong><span>Welcome, <?=h($u['name'])?>　●</span></div><div class="dash-content">
<?php if($section==='overview'):?><div class="welcome-banner mb-4"><h3 class="fw-bold">Welcome Back, <?=h($u['name'])?>!</h3><p class="mb-0">Manage your reservations and plan your next journey.</p></div><div class="row g-3 mb-4"><?php foreach([['Total Bookings',count($bookings),'📋'],['Active Bookings',$active,'🚘'],['Completed Trips',count(array_filter($bookings,fn($b)=>$b['status']==='Completed')),'✓'] ] as [$label,$num,$icon]):?><div class="col-md-4"><div class="card metric-card"><div class="card-body d-flex justify-content-between"><div><div class="text-secondary"><?=$label?></div><div class="metric-number"><?=$num?></div></div><div class="metric-icon"><?=$icon?></div></div></div></div><?php endforeach;?></div><div class="d-flex justify-content-between align-items-center mb-3"><h5 class="fw-bold mb-0">Recent Bookings</h5><a href="dashboard.php?section=bookings">View all →</a></div><?php endif;?>
<?php if($section==='bookings'||$section==='overview'):?><div class="card dash-card"><div class="card-body"><div class="table-responsive"><table class="table dash-table"><thead><tr><th>Car</th><th>Rental Dates</th><th>Days</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach(($section==='overview'?array_slice($bookings,0,5):$bookings) as $b):?><tr><td><img src="<?=h($b['image_url'])?>" class="thumb me-2" alt=""><?=h($b['car_name'])?></td><td><?=h($b['start_date'])?> – <?=h($b['end_date'])?></td><td><?=(int)$b['days']?></td><td><?=money($b['total'])?></td><td><span class="badge text-bg-<?=['Pending'=>'warning','Confirmed'=>'success','Completed'=>'secondary','Cancelled'=>'danger'][$b['status']]?>"><?=h($b['status'])?></span></td></tr><?php endforeach;?><?php if(!$bookings):?><tr><td colspan="5" class="text-center text-secondary py-4">No bookings yet. <a href="index.php#fleet">Explore cars</a>.</td></tr><?php endif;?></tbody></table></div></div></div><?php if($section==='overview'):?><a class="btn btn-success mt-3" href="index.php#fleet">+ Make a Reservation</a><?php endif;?>
<?php elseif($section==='profile'):?><h3 class="fw-bold mb-3">My Profile</h3><div class="card dash-card"><div class="card-body p-4"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="profile"><div class="mb-3"><label class="form-label text-dark">Full name</label><input class="form-control" name="name" value="<?=h($u['name'])?>" required></div><div class="mb-3"><label class="form-label text-dark">Email</label><input class="form-control" value="<?=h($u['email'])?>" disabled></div><div class="mb-3"><label class="form-label text-dark">Phone</label><input class="form-control" name="phone" value="<?=h($u['phone'])?>" required></div><button class="btn btn-primary">Save Changes</button></form></div></div><?php endif;?></div></div></div></div>
